import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.BQq6mqvm.js";const g=JSON.parse('{"title":"在线预览","description":"","frontmatter":{},"headers":[],"relativePath":"usage/preview.md","filePath":"usage/preview.md","lastUpdated":1790385461000}'),r={name:"usage/preview.md"};function c(n,t,l,i,s,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="在线预览" tabindex="-1">在线预览 <a class="header-anchor" href="#在线预览" aria-label="Permalink to &quot;在线预览&quot;">​</a></h1><p>不用下载就能查看文件内容。点击<strong>文件名</strong>或操作列的<strong>预览</strong>，会在新标签页打开预览页面。</p><h2 id="支持的类型" tabindex="-1">支持的类型 <a class="header-anchor" href="#支持的类型" aria-label="Permalink to &quot;支持的类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>格式</th><th>预览方式</th></tr></thead><tbody><tr><td>文档</td><td><code>.docx</code></td><td>渲染为网页，保留排版</td></tr><tr><td>表格</td><td><code>.xlsx</code></td><td>按工作表显示，可切换标签页</td></tr><tr><td>演示</td><td><code>.pptx</code></td><td>逐页渲染幻灯片</td></tr><tr><td>PDF</td><td><code>.pdf</code></td><td>浏览器内置阅读器</td></tr><tr><td>图片</td><td><code>png</code> <code>jpg</code> <code>jpeg</code> <code>gif</code> <code>webp</code> <code>bmp</code> <code>ico</code> <code>tiff</code></td><td>直接显示</td></tr><tr><td>文本</td><td><code>txt</code> <code>md</code> <code>csv</code> <code>log</code> <code>json</code> <code>xml</code> <code>yml</code> <code>ini</code> 及常见代码文件</td><td>等宽字体显示</td></tr><tr><td>音频</td><td><code>mp3</code> <code>wav</code> <code>m4a</code> <code>ogg</code> <code>flac</code> <code>aac</code></td><td>内置播放器</td></tr><tr><td>视频</td><td><code>mp4</code> <code>webm</code> <code>mov</code> <code>ogg</code></td><td>内置播放器，可拖动进度</td></tr></tbody></table><h2 id="不支持的类型" tabindex="-1">不支持的类型 <a class="header-anchor" href="#不支持的类型" aria-label="Permalink to &quot;不支持的类型&quot;">​</a></h2><p>以下类型<strong>无法在线预览</strong>，点击预览会提示下载后查看：</p><table tabindex="0"><thead><tr><th>类型</th><th>原因</th><th>解决办法</th></tr></thead><tbody><tr><td><code>.doc</code> <code>.xls</code> <code>.ppt</code></td><td>旧版二进制格式，浏览器无法解析</td><td>用 Office 另存为 <code>.docx</code> / <code>.xlsx</code> / <code>.pptx</code> 后重新上传</td></tr><tr><td>压缩包</td><td>需要解压才能查看</td><td>下载到本地解压</td></tr><tr><td><strong>超过可预览上限的文件</strong></td><td>文件太大，在线渲染会卡住浏览器</td><td><strong>直接下载</strong>到本地打开即可（默认上限 20 MB，由管理员在系统管理里调整）</td></tr></tbody></table><p>体积超限与格式不支持是两回事：超限的文件<strong>照样能下载</strong>，只是不再在线打开。</p><h2 id="预览页面上的操作" tabindex="-1">预览页面上的操作 <a class="header-anchor" href="#预览页面上的操作" aria-label="Permalink to &quot;预览页面上的操作&quot;">​</a></h2><p>预览页顶部有文件名、类型标签和文件大小，右侧：</p><ul><li><strong>下载</strong> —— 把文件保存到本地</li><li><strong>返回</strong> —— 回到之前的页面</li></ul><h2 id="大文件预览较慢" tabindex="-1">大文件预览较慢 <a class="header-anchor" href="#大文件预览较慢" aria-label="Permalink to &quot;大文件预览较慢&quot;">​</a></h2><p>文档和表格是在浏览器里解析的，文件较大时需要等一会儿，页面会显示「正在加载文件内容…」。</p><p>如果表格特别大，为保持流畅，<strong>只渲染前 2000 行 / 100 列</strong>，超出部分会给出提示。需要看完整内容请下载后用 Excel 打开。</p><p>超过可预览上限的文件不会走这条路径 —— 直接提示下载，省得白等。</p><h2 id="文本文件的编码" tabindex="-1">文本文件的编码 <a class="header-anchor" href="#文本文件的编码" aria-label="Permalink to &quot;文本文件的编码&quot;">​</a></h2><p>文本预览会自动识别 <strong>UTF-8</strong> 与 <strong>GBK</strong> 编码，因此 Windows 下保存的中文文本文件通常也能正常显示。</p><p>如果文件超过 4 MB，只显示前面的部分内容，避免浏览器卡顿。</p><h2 id="音视频拖动进度" tabindex="-1">音视频拖动进度 <a class="header-anchor" href="#音视频拖动进度" aria-label="Permalink to &quot;音视频拖动进度&quot;">​</a></h2><p>音频和视频支持拖动进度条。如果发现无法拖动，通常是反向代理没有透传 <code>Range</code> 请求头，请联系管理员检查。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./files">浏览与下载</a></li><li><a href="./profile">修改密码</a></li></ul>',22)])])}const b=d(r,[["render",c]]);export{g as __pageData,b as default};
